import { useEffect, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { listProviders } from "@/app/console/lib/providers";
import { MODELS, type SessionModel } from "@/app/console/lib/models";

// The pane's MODEL picker (#a-pane-can-choose-its-model-from-the-view-strip) — a view beside Log,
// rather than a row buried in the pane menu.
//
// WHY A VIEW AND NOT A MENU ROW. Every piece of this already existed — `listProviders()` has had
// seven providers registered for a long time, `ollama_models` has listed the locally-installed models
// since #1830, and a pane has carried `paneProviders`/`paneModels` throughout. What did not exist was
// anywhere to SEE them together, so choosing a local model meant knowing the launch command, and the
// launch command is the part that is not `ollama run <model>`.
//
// A menu row could not have carried it: local models are DISCOVERED (an async call to a daemon that
// may not be running), and a dropdown is the wrong shape for a list that can be empty, slow, or an
// error — each of which is a thing the reader needs told.

/** A model the pane can be switched to, and where it came from. */
interface Choice {
  providerId: string;
  providerName: string;
  /** Absent for a provider whose model is not selectable here (it carries its own default). */
  model?: SessionModel;
  label: string;
  hint: string;
}

/** Ollama's default endpoint is the backend's business; `undefined` asks it for its own default. */
const OLLAMA_BASE: string | undefined = undefined;

export interface ModelsViewProps {
  small?: boolean;
  /** The pane's current provider id (`claude` when unset — the app's default harness). */
  provider?: string;
  /** The pane's current model, when it has one of its own. */
  model?: SessionModel;
  onSelect?: (providerId: string, model?: SessionModel) => void;
  /** Relaunch the pane so the choice takes effect now. Absent ⇒ the button is not offered. */
  onRelaunch?: () => void;
}

export function ModelsView({ small = false, provider, model, onSelect, onRelaunch }: ModelsViewProps) {
  // `undefined` = still asking, `[]` = asked and there are none, a list = what is installed. The three
  // are different sentences and the panel says each of them, because "no local models" and "Ollama is
  // not running" send the reader to completely different places.
  const [local, setLocal] = useState<string[] | undefined>(undefined);
  const [localError, setLocalError] = useState<string | null>(null);
  const [dirty, setDirty] = useState(false);

  useEffect(() => {
    let alive = true;
    void (async () => {
      const models = await safeInvoke<string[] | null>(
        "ollama_models", { baseUrl: OLLAMA_BASE }, null,
        // NOT a thrown error: Ollama not running is the ordinary case on a machine that does not use
        // it, and a red panel would be wrong. It is reported as a state, not a failure.
        () => { if (alive) setLocalError("Ollama is not reachable — start it to list local models."); },
      );
      if (!alive) return;
      setLocal(models ?? []);
    })();
    return () => { alive = false; };
  }, []);

  const current = provider ?? "claude";
  const choices: Choice[] = [];
  // The CLAUDE tiers, which are the only models this app maps to a CLI flag itself.
  for (const m of MODELS) {
    choices.push({
      providerId: "claude", providerName: "Claude Code", model: m.id,
      label: m.id, hint: `${m.tone} · ${m.price}`,
    });
  }
  // The LOCAL models, one row each — this is the list that made the CLI hard to reach for.
  //
  // providerId is "bsc-agent", NOT "ollama" (bsc request 174). "ollama" names the raw-REPL
  // provider (`ollama run <model>` — no tools, no skills, no BSC_AGENT_PERMS, no num_ctx, no
  // CLAUDE.md chain); buildAgentEnv only assembles the BSC_AGENT_* env for `providerId ===
  // "bsc-agent"`. Mirrors how the Claude tier rows above emit "claude".
  for (const m of local ?? []) {
    choices.push({
      providerId: "bsc-agent", providerName: "Ollama", model: m,
      label: m, hint: "local · ollama",
    });
  }
  // Every OTHER registered provider, so nothing in the registry is unreachable from the UI. They carry
  // their own model default, so no model is set for them here.
  for (const p of listProviders()) {
    if (p.id === "claude" || p.id === "ollama") continue;
    choices.push({
      providerId: p.id, providerName: p.displayName, label: p.displayName,
      hint: p.prereqProbe ? `runs ${p.displayName} · ${p.prereqProbe}` : `runs ${p.displayName}`,
    });
  }

  const isCurrent = (c: Choice) =>
    c.providerId === current && (c.model === undefined ? !model : c.model === model);

  return (
    <Box style={{ flex: 1, minHeight: 0, overflow: "auto", padding: small ? "6px 10px" : "10px 14px" }}>
      {choices.map((c) => {
        const on = isCurrent(c);
        return (
          <Row
            key={`${c.providerId}:${c.model ?? "-"}`}
            data-testid={`model-choice-${c.providerId}-${c.model ?? "default"}`}
            aria-current={on ? "true" : undefined}
            onClick={() => { onSelect?.(c.providerId, c.model); setDirty(true); }}
            style={{
              gap: 8, alignItems: "baseline", cursor: onSelect ? "pointer" : "default",
              padding: "4px 6px", borderRadius: 6,
              background: on ? "var(--bg-raised)" : "transparent",
            }}
          >
            <Text style={{ fontWeight: on ? 600 : 400 }}>{c.label}</Text>
            <Text style={{ opacity: 0.6, fontSize: "0.85em" }}>{c.hint}</Text>
            {on && <Text style={{ opacity: 0.6, fontSize: "0.85em" }}>· current</Text>}
          </Row>
        );
      })}

      {/* The three states of the local list, said apart. */}
      {localError && <Text style={{ opacity: 0.7, fontSize: "0.85em" }}>{localError}</Text>}
      {!localError && local === undefined && (
        <Text style={{ opacity: 0.7, fontSize: "0.85em" }}>Looking for local models…</Text>
      )}
      {!localError && local?.length === 0 && (
        <Text style={{ opacity: 0.7, fontSize: "0.85em" }}>
          No local models installed — `ollama pull &lt;model&gt;` adds one.
        </Text>
      )}

      {/* A CHOICE IS NOT A RELAUNCH. The pane's provider/model are read at launch, so a live session
          keeps running whatever it started with; saying so beats a picker that looks applied and is
          not. The button is how you apply it, deliberately, without losing a conversation by accident. */}
      <Row style={{ gap: 8, alignItems: "center", marginTop: 8 }}>
        <Text style={{ opacity: 0.7, fontSize: "0.85em" }}>
          {dirty ? "Takes effect on the pane's next launch." : "Applies to the pane's next launch."}
        </Text>
        {onRelaunch && (
          <Button data-testid="models-relaunch" onClick={onRelaunch}>Relaunch now</Button>
        )}
      </Row>
    </Box>
  );
}

